DROP DATABASE IF EXISTS BDIADelivery;
CREATE DATABASE BDIADelivery CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE BDIADelivery;

CREATE TABLE Clientes (
    IdCliente INT AUTO_INCREMENT PRIMARY KEY,
    Nombre VARCHAR(150) NOT NULL,
    CIF VARCHAR(20) UNIQUE,
    Telefono VARCHAR(20),
    Email VARCHAR(150)
) ENGINE=InnoDB;

CREATE TABLE Provincias (
    IdProvincia INT AUTO_INCREMENT PRIMARY KEY,
    Nombre VARCHAR(150) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE Destinos (
    IdDestino INT AUTO_INCREMENT PRIMARY KEY,
    Direccion VARCHAR(200) NOT NULL,
    Ciudad VARCHAR(100) NOT NULL,
    IdProvincia INT,
    Pais VARCHAR(50) NOT NULL,
    CodigoPostal VARCHAR(10),
    Latitud DECIMAL(10,7),
    Longitud DECIMAL(10,7),
    Coordenadas POINT NOT NULL SRID 4326,
    CONSTRAINT FK_Destinos_Provincias FOREIGN KEY (IdProvincia) REFERENCES Provincias(IdProvincia)
) ENGINE=InnoDB;

CREATE TABLE Productos (
    IdProducto INT AUTO_INCREMENT PRIMARY KEY,
    Nombre VARCHAR(150) NOT NULL,
    PrecioVenta DECIMAL(10,2) NOT NULL,
    TiempoFabricacionMedioDias INT NOT NULL CHECK (TiempoFabricacionMedioDias >= 0),
    CaducidadDias INT NOT NULL CHECK (CaducidadDias > 0)
) ENGINE=InnoDB;

CREATE TABLE Pedidos (
    IdPedido BIGINT AUTO_INCREMENT PRIMARY KEY,
    FechaPedido DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    IdCliente INT NOT NULL,
    IdDestino INT NOT NULL,
    CONSTRAINT FK_Pedidos_Clientes FOREIGN KEY (IdCliente) REFERENCES Clientes(IdCliente),
    CONSTRAINT FK_Pedidos_Destinos FOREIGN KEY (IdDestino) REFERENCES Destinos(IdDestino)
) ENGINE=InnoDB;

CREATE TABLE LineasPedido (
    IdPedido BIGINT NOT NULL,
    NumeroLinea SMALLINT NOT NULL,
    IdProducto INT NOT NULL,
    Cantidad SMALLINT NOT NULL CHECK (Cantidad BETWEEN 1 AND 500),
    PRIMARY KEY (IdPedido, NumeroLinea),
    CONSTRAINT FK_LineasPedido_Pedido FOREIGN KEY (IdPedido) REFERENCES Pedidos(IdPedido),
    CONSTRAINT FK_LineasPedido_Producto FOREIGN KEY (IdProducto) REFERENCES Productos(IdProducto)
) ENGINE=InnoDB;

